  assert.equal(old.technicalFindings.fullImplementationValidated,false);assert.equal(row.technicalFindings.fullImplementationValidated,false);
  assert.equal(isCorpusSolutionReviewed(old),true);assert.equal(isCorpusSolutionReviewed(row),true);
  assert.equal(old.materialStatus.solution,'retrieved-and-reviewed');assert(!Object.hasOwn(row,'subsequentSolutionReviews'));
  assert.deepEqual(Object.keys(row).filter(key=>!Object.hasOwn(old,key)),['resolution']);
